insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 5, 'Não me disse ele: É minha irmã; e ela também disse: É meu irmão? Com sinceridade de meu coração, e com limpeza de minhas mãos fiz isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 6, 'E disse-lhe Deus em sonhos: Eu também sei que com integridade de teu coração fizeste isto; e eu também te detive de pecar contra mim, e assim não te permiti que a tocasses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 7, 'Agora, pois, devolve a mulher a seu marido; porque é profeta, e orará por ti, e viverás. E se tu não a devolveres, sabe que certamente morrerás, com tudo o que for teu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 8, 'Então Abimeleque se levantou de manhã, e chamou a todos os seus servos, e disse todas estas palavras aos ouvidos deles; e temeram os homens em grande maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 9, 'Depois chamou Abimeleque a Abraão e lhe disse: Que nos fizeste? e em que pequei eu contra ti, que atraíste sobre mim e sobre meu reino tão grande pecado? o que não devias fazer fizeste comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 10, 'E disse mais Abimeleque a Abraão: Que viste para que fizesses isto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 11, 'E Abraão respondeu: Porque disse para mim: Certamente não há temor de Deus neste lugar, e me matarão por causa de minha mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 12, 'E na verdade também é minha irmã, filha de meu pai, mas não filha de minha mãe, e tomei-a por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 13, 'E foi que, quando Deus me fez sair sem rumo da casa de meu pai, eu lhe disse: Esta é a lealdade que tu me farás, que em todos os lugares onde chegarmos, digas de mim: É meu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 14, 'Então Abimeleque tomou ovelhas e vacas, e servos e servas, e deu-o a Abraão, e devolveu-lhe a Sara sua mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 15, 'E disse Abimeleque: Eis que minha terra está diante de ti, habita onde bem te parecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 16, 'E a Sara disse: Eis que dei mil moedas de prata a teu irmão; olha que ele te é por véu de olhos para todos os que estão contigo, e para com todos: assim foi repreendida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 17, 'Então Abraão orou a Deus; e Deus sanou a Abimeleque e a sua mulher, e a suas servas, e voltaram a ter filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 20, 18, 'Porque havia por completo fechado o SENHOR toda madre da casa de Abimeleque, por causa de Sara, mulher de Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 1, 'E o SENHOR visitou Sara, como disse, e o SENHOR fez com Sara como havia falado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 2, 'E concebeu e deu à luz Sara a Abraão um filho em sua velhice, no tempo que Deus lhe havia dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 3, 'E chamou Abraão o nome de seu filho que lhe nasceu, que lhe deu à luz Sara, Isaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 4, 'E circuncidou Abraão a seu filho Isaque de oito dias, como Deus lhe havia mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 5, 'E era Abraão de cem anos, quando lhe nasceu Isaque seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 6, 'Então disse Sara: Deus me fez rir, e qualquer um que o ouvir, se rirá comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 7, 'E acrescentou: Quem diria a Abraão que Sara havia de dar de mamar a filhos? pois que lhe dei um filho em sua velhice.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 8, 'E cresceu o menino, e foi desmamado; e fez Abraão grande banquete no dia que foi desmamado Isaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 9, 'E viu Sara ao filho de Agar a egípcia, o qual havia esta dado a Abraão, que o ridicularizava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 10, 'Portanto disse a Abraão: Expulsa a esta serva e a seu filho; que o filho desta serva não herdará com meu filho, com Isaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 11, 'Este dito pareceu grave em grande maneira a Abraão por causa de seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 12, 'Então disse Deus a Abraão: Não te pareça grave por causa do jovem e de tua serva; em tudo o que te disser Sara, ouve sua voz, porque em Isaque será chamada tua descendência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 13, 'E também do filho da serva farei nação, porque é descendência tua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 14, 'Então Abraão se levantou manhã muito cedo, e tomou pão, e um odre de água, e deu-o a Agar, pondo-o sobre seu ombro, e entregou-lhe o jovem, e despediu-a. E ela partiu, e andava errante pelo deserto de Berseba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 15, 'E faltou a água do odre, e deitou ao jovem debaixo de uma árvore;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 16, 'E foi-se e sentou-se em frente, afastando-se como um tiro de arco; porque dizia: Não verei quando o jovem morrer: e sentou-se em frente, e levantou sua voz e chorou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 17, 'E ouviu Deus a voz do jovem; e o anjo de Deus chamou a Agar desde o céu, e lhe disse: Que tens, Agar? Não temas; porque Deus ouviu a voz do jovem onde está.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 18, 'Levanta-te, ergue ao jovem, e pegue-o por tua mão, porque farei dele uma grande nação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 19, 'Então abriu Deus os olhos dela, e ela viu uma fonte de água; e foi, e encheu o odre de água, e deu de beber ao jovem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 20, 'E foi Deus com o jovem; e cresceu, e habitou no deserto, e foi atirador de arco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 21, 'E habitou no deserto de Parã; e sua mãe lhe tomou mulher da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 22, 'E aconteceu naquele mesmo tempo que falou Abimeleque, e Ficol, príncipe de seu exército, a Abraão dizendo: Deus é contigo em tudo quanto fazes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 23, 'Agora, pois, jura-me aqui por Deus, que não tratarás com falsidade a mim, nem a meu filho, nem a meu neto; mas sim que conforme a bondade que eu fiz contigo, farás tu comigo e com a terra onde peregrinaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 24, 'E respondeu Abraão: Eu jurarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 25, 'E Abraão reclamou com Abimeleque por causa de um poço de água, que os servos de Abimeleque lhe haviam tirado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 26, 'E respondeu Abimeleque: Não sei quem tenha feito isto, nem tampouco tu me fizeste saber, nem eu o ouvi até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 27, 'E tomou Abraão ovelhas e vacas, e deu a Abimeleque; e fizeram ambos aliança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 28, 'E pôs Abraão sete cordeiras do rebanho à parte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 29, 'E disse Abimeleque a Abraão: Que significam essas sete cordeiras que puseste à parte?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 30, 'E ele respondeu: Que estas sete cordeiras tomarás de minha mão, para que me sejam em testemunho de que eu cavei este poço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 31, 'Por isto chamou a aquele lugar Berseba; porque ali ambos juraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 32, 'Assim fizeram aliança em Berseba: e levantaram-se Abimeleque e Ficol, príncipe de seu exército, e se voltaram à terra dos filisteus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 33, 'E plantou Abraão um bosque em Berseba, e invocou ali o nome do SENHOR Deus eterno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 21, 34, 'E morou Abraão na terra dos filisteus por muitos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 1, 'E aconteceu, depois dessas coisas, que Deus provou Abraão, e disse-lhe: Abraão. E ele respondeu: Eis-me aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 2, 'E disse: Toma agora teu filho, teu único, Isaque, a quem amas, e vai à terra de Moriá, e oferece-o ali em holocausto sobre um dos montes que eu te direi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 3, 'E Abraão se levantou manhã muito cedo, e preparou seu asno, e tomou consigo dois servos seus, e a Isaque seu filho: e cortou lenha para o holocausto, e levantou-se, e foi ao lugar que Deus lhe disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 4, 'Ao terceiro dia levantou Abraão seus olhos, e viu o lugar de longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 5, 'Então disse Abraão a seus servos: Esperai aqui com o asno, e eu e o jovem iremos até ali, e adoraremos, e voltaremos a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 6, 'E tomou Abraão a lenha do holocausto, e a pôs sobre Isaque seu filho: e ele tomou em sua mão o fogo e a espada; e foram ambos juntos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 7, 'Então falou Isaque a Abraão seu pai, e disse: Meu pai. e ele respondeu: Eis-me aqui, meu filho. E ele disse: Eis aqui o fogo e a lenha; mas onde está o cordeiro para o holocausto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 8, 'E respondeu Abraão: Deus se proverá de cordeiro para o holocausto, filho meu. E iam juntos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 9, 'E quando chegaram ao lugar que Deus lhe havia dito, edificou ali Abraão um altar, e compôs a lenha, e amarrou a Isaque seu filho, e pôs-lhe no altar sobre a lenha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 10, 'E estendeu Abraão sua mão, e tomou a espada, para degolar a seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 11, 'Então o anjo do SENHOR lhe gritou do céu, e disse: Abraão, Abraão. E ele respondeu: Eis-me aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 12, 'E disse: Não estendas tua mão sobre o jovem, nem lhe faças nada; que já conheço que temes a Deus, pois que não me recusaste o teu filho, o teu único;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 13, 'Então levantou Abraão seus olhos, e olhou, e eis um carneiro a suas costas preso em um arbusto por seus chifres: e foi Abraão, e tomou o carneiro, e ofereceu-lhe em holocausto em lugar de seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 14, 'E chamou Abraão o nome daquele lugar, O SENHOR proverá. Portanto se diz hoje: No monte do SENHOR se proverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 15, 'E chamou o anjo do SENHOR a Abraão segunda vez desde o céu,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 16, 'E disse: Por mim mesmo jurei, diz o SENHOR, que porquanto fizeste isto, e não me recusaste teu filho, teu único;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 17, 'certamente te abençoarei, e multiplicarei tua descendência como as estrelas do céu, e como a areia que está na beira do mar; e tua descendência possuirá as portas de seus inimigos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 18, 'Em tua descendência serão abençoadas todas as nações da terra, porquanto obedeceste à minha voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 19, 'E voltou Abraão a seus servos, e levantaram-se e se foram juntos a Berseba; e habitou Abraão em Berseba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 20, 'E aconteceu depois destas coisas, que foi dada notícia a Abraão, dizendo: Eis que também Milca havia dado à luz filhos a teu irmão Naor:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 21, 'A Uz, seu primogênito, e a Buz, seu irmão, e a Quemuel, pai de Arã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 22, 'E a Quésede, e a Hazo, e a Pildas, e a Jidlafe, e a Betuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 23, 'E Betuel gerou Rebeca. Milca deu à luz estes oito de Naor, irmão de Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 22, 24, 'E sua concubina, que se chamava Reumá, deu à luz também a Tebá, e a Gaã, e a Taás, e a Maaca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 1, 'E foi a vida de Sara cento e vinte e sete anos; estes foram os anos da vida de Sara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 2, 'E morreu Sara em Quiriate-Arba, que é Hebrom, na terra de Canaã; e Abraão veio para ficar de luto por Sara e para chorar por ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 3, 'E levantou-se Abraão de diante de sua morta, e falou aos filhos de Hete, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 4, 'Peregrino e estrangeiro sou entre vós; dá-me propriedade de sepultura convosco, e sepultarei minha falecida de diante de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 5, 'E responderam os filhos de Hete a Abraão, e disseram-lhe:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 6, 'Ouve-nos, senhor meu, és um príncipe de Deus entre nós; no melhor de nossas sepulturas sepulta a tua falecida; nenhum de nós te impedirá sua sepultura, para que enterres tua falecida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 7, 'E Abraão se levantou, e inclinou-se ao povo daquela terra, aos filhos de Hete;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 8, 'E falou com eles, dizendo: Se queres que eu sepulte minha falecida de diante de mim, ouvi-me, e intercedei por mim com Efrom, filho de Zoar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 9, 'Para que me dê a caverna de Macpela, que tem na extremidade de sua propriedade: que por seu justo preço a dê a mim, para possessão de sepultura em meio de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 10, 'Este Efrom achava-se entre os filhos de Hete: e respondeu Efrom Heteu a Abraão, aos ouvidos dos filhos de Hete, de todos os que entravam pela porta de sua cidade, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 11, 'Não, senhor meu, ouve-me: eu te dou a propriedade, e te dou também a caverna que está nela; diante dos filhos de meu povo a dou a ti; sepulta tua falecida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 12, 'E Abraão se inclinou diante do povo da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 13, 'E respondeu a Efrom aos ouvidos do povo da terra, dizendo: Antes, se for do teu agrado, rogo-te que me ouças; eu darei o preço da propriedade, toma-o de mim, e sepultarei nela minha falecida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 14, 'E respondeu Efrom a Abraão, dizendo-lhe:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 15, 'Senhor meu, escuta-me: a terra vale quatrocentos siclos de prata: que é isto entre mim e ti? Enterra, pois, tua falecida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 16, 'Então Abraão concordou com Efrom, e pesou Abraão a Efrom o dinheiro que disse, ouvindo-o os filhos de Hete, quatrocentos siclos de prata, de acordo com o padrão dos mercadores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 17, 'E ficou a propriedade de Efrom que estava em Macpela em frente de Manre, a propriedade e a caverna que estava nela, e todas as árvores que havia na herança, e em todo o seu termo ao derredor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 18, 'Para Abraão em possessão, à vista dos filhos de Hete, e de todos os que entravam pela porta da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 19, 'E depois disto sepultou Abraão a Sara, sua mulher, na caverna da propriedade de Macpela em frente de Manre, que é Hebrom na terra de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 23, 20, 'E ficou a propriedade e a caverna que nela havia, para Abraão, em possessão de sepultura adquirida dos filhos de Hete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 1, 'E Abraão era velho, e cheio de dias; e o SENHOR havia abençoado a Abraão em tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 2, 'E disse Abraão a um criado seu, o mais velho de sua casa, que era o que governava em tudo o que tinha: Põe agora tua mão debaixo de minha coxa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 3, 'E te juramentarei pelo SENHOR, Deus dos céus e Deus da terra, que não tomarás mulher para meu filho das filhas dos cananeus, entre os quais eu habito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 4, 'Em vez disso irás à minha terra e à minha parentela, e tomarás mulher para meu filho Isaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 5, 'E o criado lhe respondeu: Talvez a mulher não queira vir atrás de mim a esta terra; farei voltar, pois, teu filho à terra de onde saíste?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 6, 'E Abraão lhe disse: Guarda-te que não faças voltar a meu filho ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 7, 'O SENHOR, Deus dos céus, que me tomou da casa de meu pai e da terra de minha parentela, e me falou e me jurou, dizendo: À tua descendência darei esta terra; ele enviará seu anjo diante de ti, e tu tomarás dali mulher para meu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 8, 'E se a mulher não quiser vir atrás de ti, serás livre deste meu juramento; somente que não faças voltar ali a meu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 9, 'Então o criado pôs sua mão debaixo da coxa de Abraão seu senhor, e jurou-lhe sobre este negócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 10, 'E o criado tomou dez camelos dos camelos de seu senhor, e foi-se, pois tinha à sua disposição todos os bens de seu senhor: e posto em caminho, chegou à Mesopotâmia, à cidade de Naor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 11, 'E fez ajoelhar os camelos fora da cidade, junto a um poço de água, à hora da tarde, à hora em que saem as moças por água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 12, 'E disse: SENHOR, Deus de meu senhor Abraão, dá-me, te rogo, o ter hoje bom encontro, e faze misericórdia com meu senhor Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 13, 'Eis que eu estou junto à fonte de água, e as filhas dos homens desta cidade saem por água:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 14, 'Seja, pois, que a moça a quem eu disser: Baixa teu cântaro, te rogo, para que eu beba; e ela responder: Bebe, e também darei de beber a teus camelos: que seja esta a que tu destinaste para teu servo Isaque; e nisto conhecerei que haverás feito misericórdia com meu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 15, 'E aconteceu que antes que ele acabasse de falar, eis que Rebeca, que havia nascido a Betuel, filho de Milca, mulher de Naor irmão de Abraão, a qual saía com seu cântaro sobre seu ombro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 16, 'E a moça era de muito belo aspecto, virgem, à que homem não havia conhecido; a qual desceu à fonte, e encheu seu cântaro, e se voltava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 17, 'Então o criado correu até ela, e disse: Rogo-te que me dês a beber um pouco de água de teu cântaro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 18, 'E ela respondeu: Bebe, meu senhor; e apressou-se a baixar seu cântaro sobre sua mão, e lhe deu a beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 19, 'E quando acabou de dar-lhe de beber, disse: Também para teus camelos tirarei água, até que acabem de beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 20, 'E apressou-se, e esvaziou seu cântaro no bebedouro, e correu outra vez ao poço para tirar água, e tirou para todos os seus camelos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 21, 'E o homem estava maravilhado dela, permanecendo calado, para saber se o SENHOR havia prosperado ou não sua viagem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 22, 'E foi que quando os camelos acabaram de beber, presenteou-lhe o homem um pendente de ouro que pesava meio siclo, e dois braceletes que pesavam dez;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 23, 'E disse: De quem és filha? Rogo-te me digas, há lugar em casa de teu pai onde possamos passar a noite?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 24, 'E ela respondeu: Sou filha de Betuel, filho de Milca, o qual deu à luz ela a Naor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 25, 'E acrescentou: Também há em nossa casa palha e muita forragem, e lugar para passar a noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 26, 'O homem então se inclinou, e adorou ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 27, 'E disse: Bendito seja o SENHOR, Deus de meu senhor Abraão, que não afastou sua misericórdia e sua verdade de meu senhor, guiando-me o SENHOR no caminho à casa dos irmãos de meu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 28, 'E a moça correu, e fez saber na casa de sua mãe estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 29, 'E Rebeca tinha um irmão que se chamava Labão, o qual correu fora ao homem, à fonte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 30, 'E foi que quando viu o pendente e os braceletes nas mãos de sua irmã, que dizia, Assim me falou aquele homem; veio a ele: e eis que estava junto aos camelos à fonte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 31, 'E disse-lhe: Vem, bendito do SENHOR; por que estás fora? eu limpei a casa, e o lugar para os camelos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 32, 'Então o homem veio à casa, e Labão desatou os camelos; e deu-lhes palha e forragem, e água para lavar os pés dele, e os pés dos homens que com ele vinham.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 33, 'E puseram diante dele comida; mas ele disse: Não comerei até que tenha dito minha mensagem. E ele lhe disse: Fala.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 34, 'Então disse: Eu sou criado de Abraão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 35, 'E o SENHOR abençoou muito a meu senhor, e ele se engrandeceu: e lhe deu ovelhas e vacas, prata e ouro, servos e servas, camelos e asnos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 36, 'E Sara, mulher de meu senhor, deu à luz em sua velhice um filho a meu senhor, quem lhe deu tudo quanto tem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 37, 'E meu senhor me fez jurar, dizendo: Não tomarás mulher para meu filho das filhas dos cananeus, em cuja terra habito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 38, 'Em vez disso irás à casa de meu pai, e à minha parentela, e tomarás mulher para meu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 39, 'E eu disse: Talvez a mulher não queira me seguir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 40, 'Então ele me respondeu: O SENHOR, em cuja presença tenho andado, enviará seu anjo contigo, e fará teu caminho ser bem-sucedido; e tomarás mulher para meu filho de minha linhagem e da casa de meu pai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 41, 'Então serás livre de meu juramento, quando houveres chegado à minha linhagem; e se não a derem a ti, serás livre de meu juramento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 42, 'Cheguei, pois, hoje à fonte, e disse: SENHOR, Deus de meu senhor Abraão, se tu fazes bem-sucedido agora meu caminho pelo qual ando;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 43, 'Eis que eu estou junto à fonte de água; seja, pois, que a virgem que sair por água, à qual disser: Dá-me de beber, te rogo, um pouco de água de teu cântaro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 44, 'E ela me responder, Bebe tu, e também para teus camelos tirarei água: esta seja a mulher que destinou o SENHOR para o filho de meu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 45, 'E antes que acabasse de falar em meu coração, eis que Rebeca saía com seu cântaro sobre seu ombro; e desceu à fonte, e tirou água; e lhe disse: Rogo-te que me dês de beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 46, 'E prontamente baixou seu cântaro de cima de si, e disse: Bebe, e também a teus camelos darei a beber. E bebi, e deu também de beber a meus camelos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 47, 'Então lhe perguntei, e disse: De quem és filha? E ela respondeu: Filha de Betuel, filho de Naor, que Milca lhe deu. Então pus nela um pendente sobre seu nariz, e braceletes sobre suas mãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 48, 'E inclinei-me, e adorei ao SENHOR, e bendisse ao SENHOR, Deus de meu senhor Abraão, que me havia guiado pelo caminho de verdade para tomar a filha do irmão de meu senhor para seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 49, 'Agora, pois, se vós fazeis misericórdia e verdade com meu senhor, declarai-o a mim; e se não, declarai-o a mim; e irei embora à direita ou à esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 50, 'Então Labão e Betuel responderam e disseram: Do SENHOR saiu isto; não podemos falar-te mal nem bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 51, 'Eis aí Rebeca diante de ti; toma-a e vai-te, e seja mulher do filho de teu senhor, como o disse o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 52, 'E foi, que quando o criado de Abraão ouviu suas palavras, inclinou-se à terra ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 53, 'E o criado tirou objetos de prata, objetos de ouro e roupas, e deu a Rebeca: também deu coisas preciosas a seu irmão e a sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 54, 'E comeram e beberam ele e os homens que vinham com ele, e dormiram; e levantando-se de manhã, disse: Autorizai-me voltar a meu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 55, 'Então respondeu seu irmão e sua mãe: Espere a moça conosco ao menos dez dias, e depois irá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 56, 'E ele lhes disse: Não me detenhais, pois que o SENHOR fez prosperar meu caminho; despede-me para que me vá a meu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 57, 'Eles responderam então: Chamemos a moça e perguntemos a ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 58, 'E chamaram a Rebeca, e disseram-lhe: Irás tu com este homem? E ela respondeu: Sim, irei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 59, 'Então deixaram ir a Rebeca sua irmã, e à sua criada, e ao criado de Abraão e a seus homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 60, 'E abençoaram a Rebeca, e disseram-lhe: És nossa irmã; sejas em milhares de milhares, e tua geração possua a porta de seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 61, 'Levantou-se então Rebeca e suas moças, e subiram sobre os camelos, e seguiram ao homem; e o criado tomou a Rebeca, e foi embora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 62, 'E vinha Isaque do poço do Vivente que me vê; porque ele habitava na terra do Sul;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 63, 'E havia saído Isaque a orar ao campo, à hora da tarde; e levantando seus olhos, olhou, e eis os camelos que vinham.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 64, 'Rebeca também levantou seus olhos, e viu a Isaque, e desceu do camelo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 65, 'Porque havia perguntado ao criado: Quem é este homem que vem pelo campo até nós? E o servo havia respondido: Este é meu senhor. Ela então tomou o véu, e cobriu-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 66, 'Então o criado contou a Isaque tudo o que havia feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 24, 67, 'E trouxe-a Isaque à tenda de sua mãe Sara, e tomou a Rebeca por mulher; e amou-a: e consolou-se Isaque depois da morte de sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 1, 'E Abraão tomou outra mulher, cujo nome foi Quetura;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 2, 'A qual lhe deu à luz a Zinrã, e a Jocsã, e a Medã, e a Midiã, e a Jisbaque, e a Suá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 3, 'E Jocsã gerou a Seba, e a Dedã: e filhos de Dedã foram Assurim, e Letusim, e Leummim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 4, 'E filhos de Midiã: Efá, e Efer, e Enoque, e Abida, e Elda. Todos estes foram filhos de Quetura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 5, 'Mas Abraão deu tudo quanto tinha a Isaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 6, 'E aos filhos de suas concubinas deu Abraão presentes, e enviou-os para longe de Isaque seu filho, enquanto ele vivia, até o oriente, à terra oriental.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 7, 'E estes foram os dias de vida que viveu Abraão: cento e setenta e cinco anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 8, 'E expirou, e morreu Abraão em boa velhice, ancião e cheio de dias e foi unido a seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 9, 'E sepultaram-no Isaque e Ismael seus filhos na caverna de Macpela, na propriedade de Efrom, filho de Zoar Heteu, que está em frente de Manre;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 10, 'Herança que comprou Abraão dos filhos de Hete; ali foi Abraão sepultado, e Sara sua mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 11, 'E sucedeu, depois de morto Abraão, que Deus abençoou a Isaque seu filho: e habitou Isaque junto a Beer-Laai-Roi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 12, 'E estas são as gerações de Ismael, filho de Abraão, que lhe deu à luz Agar egípcia, serva de Sara:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 13, 'Estes, pois, são os nomes dos filhos de Ismael, por seus nomes, por suas linhagens: O primogênito de Ismael, Nebaiote; logo Quedar, e Adbeel, e Mibsão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 14, 'E Misma, e Dumá, e Massá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 15, 'Hadade, e Tema, e Jetur, e Nafis, e Quedemá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 16, 'Estes são os filhos de Ismael, e estes seus nomes por suas vilas e por seus acampamentos; doze príncipes por suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 17, 'E estes foram os anos da vida de Ismael, cento e trinta e sete anos: e expirou Ismael, e morreu; e foi unido a seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 18, 'E habitaram desde Havilá até Sur, que está em frente do Egito vindo a Assíria; e morreu em presença de todos os seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 19, 'E estas são as gerações de Isaque, filho de Abraão. Abraão gerou a Isaque:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 20, 'E era Isaque de quarenta anos quando tomou por mulher a Rebeca, filha de Betuel arameu de Padã-Arã, irmã de Labão arameu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 21, 'E orou Isaque ao SENHOR por sua mulher, que era estéril; e aceitou-o o SENHOR, e concebeu Rebeca sua mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 22, 'E os filhos se combatiam dentro dela; e disse: Se é assim para que vivo eu? E foi consultar ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 23, 'E respondeu-lhe o SENHOR: Duas nações há em teu ventre, E dois povos serão divididos desde tuas entranhas: E um povo será mais forte que o outro povo, e o maior servirá ao menor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 24, 'E quando se cumpriram seus dias para dar à luz, eis que havia gêmeos em seu ventre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 25, 'E saiu o primeiro ruivo, e todo ele peludo como uma veste; e chamaram seu nome Esaú.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 26, 'E depois saiu seu irmão, pegando com sua mão o calcanhar de Esaú: e foi chamado seu nome Jacó. E era Isaque de idade de sessenta anos quando ela os deu à luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 27, 'E cresceram os meninos, e Esaú foi hábil na caça, homem do campo: Jacó porém era homem quieto, que habitava em tendas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 28, 'E amou Isaque a Esaú, porque comia de sua caça; mas Rebeca amava a Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 29, 'E cozinhou Jacó um guisado; e voltando Esaú do campo cansado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 30, 'Disse a Jacó: Rogo-te que me dês a comer disso vermelho, pois estou muito cansado. Portanto foi chamado seu nome Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 31, 'E Jacó respondeu: Vende-me neste dia tua primogenitura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 32, 'Então disse Esaú: Eis que vou morrer; para que, pois, me servirá a primogenitura?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 33, 'E disse Jacó: Jura-me hoje. E ele lhe jurou, e vendeu a Jacó sua primogenitura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 25, 34, 'Então Jacó deu a Esaú pão e do guisado das lentilhas; e ele comeu e bebeu, e levantou-se, e foi-se. Assim menosprezou Esaú a primogenitura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 1, 'E houve fome na terra, além da primeira fome que foi nos dias de Abraão: e foi-se Isaque a Abimeleque rei dos filisteus, em Gerar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 2, 'E apareceu-lhe o SENHOR, e disse-lhe: Não desças ao Egito: habita na terra que eu te disser;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 3, 'Habita nesta terra, e serei contigo, e te abençoarei; porque a ti e à tua descendência darei todas estas terras, e confirmarei o juramento que jurei a Abraão teu pai:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 4, 'E multiplicarei tua descendência como as estrelas do céu, e darei à tua descendência todas estas terras; e todas as nações da terra serão abençoadas em tua descendência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 5, 'Porquanto ouviu Abraão minha voz, e guardou meu preceito, meus mandamentos, meus estatutos e minhas leis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 6, 'Habitou, pois, Isaque em Gerar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 7, 'E os homens daquele lugar lhe perguntaram acerca de sua mulher; e ele respondeu: É minha irmã; porque teve medo de dizer: É minha mulher; que talvez, disse, os homens do lugar me matem por causa de Rebeca; porque era de belo aspecto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 8, 'E sucedeu que, depois que ele esteve ali muitos dias, Abimeleque, rei dos filisteus, olhando por uma janela, viu a Isaque que acariciava Rebeca sua mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 9, 'E chamou Abimeleque a Isaque, e disse: Eis que ela é certamente tua mulher: como, pois, disseste: É minha irmã? E Isaque lhe respondeu: Porque disse: Talvez eu morra por causa dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 10, 'E Abimeleque disse: Por que nos fizeste isto? Por pouco haveria dormido alguém do povo com tua mulher, e haverias trazido sobre nós o pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 11, 'Então Abimeleque mandou a todo o povo, dizendo: O que tocar a este homem ou a sua mulher certamente morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 12, 'E semeou Isaque naquela terra, e achou aquele ano cem por um: e o SENHOR o abençoou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 13, 'E o homem se engrandeceu, e foi engrandecendo-se cada vez mais, até fazer-se muito poderoso:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 14, 'E teve rebanho de ovelhas, e rebanho de vacas, e grande número de servos; e os filisteus tiveram inveja dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 15, 'E todos os poços que os criados de Abraão seu pai haviam aberto em seus dias, os filisteus os haviam fechado e enchido da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 16, 'E disse Abimeleque a Isaque: Aparta-te de nós, porque muito mais poderoso que nós te fizeste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 17, 'E Isaque se foi dali; e assentou suas tendas no vale de Gerar, e habitou ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 18, 'E voltou a abrir Isaque os poços de água que haviam aberto nos dias de Abraão seu pai, e que os filisteus haviam fechado, depois de Abraão ter morrido; e chamou-os pelos nomes que seu pai os havia chamado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 19, 'E os servos de Isaque cavaram no vale, e acharam ali um poço de águas vivas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 20, 'E os pastores de Gerar brigaram com os pastores de Isaque, dizendo: A água é nossa: por isso chamou o nome do poço Eseque, porque haviam brigado com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 21, 'E abriram outro poço, e também brigaram sobre ele: e chamou seu nome Sitna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 22, 'E apartou-se dali, e abriu outro poço, e não brigaram sobre ele: e chamou seu nome Reobote, e disse: Porque agora nos fez alargar o SENHOR e frutificaremos na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 23, 'E dali subiu a Berseba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 24, 'E apareceu-lhe o SENHOR aquela noite, e disse: Eu sou o Deus de Abraão teu pai: não temas, que eu sou contigo, e eu te abençoarei, e multiplicarei tua descendência por causa do meu servo Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 25, 'E edificou ali um altar, e invocou o nome do SENHOR, e estendeu ali sua tenda: e abriram ali os servos de Isaque um poço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 26, 'E Abimeleque veio a ele desde Gerar, e Auzate, amigo seu, e Ficol, capitão de seu exército.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 27, 'E disse-lhes Isaque: Por que vindes a mim, pois que haveis me odiado, e me expulsastes dentre vós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 28, 'E eles responderam: Vimos que o SENHOR é contigo; e dissemos: Haja agora juramento entre nós, entre nós e ti, e faremos aliança contigo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 29, 'Que não nos faças mal, como nós não te tocamos, y como somente te fizemos bem, e te enviamos em paz: tu agora, bendito do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 30, 'Então ele lhes fez banquete, e comeram e beberam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 31, 'E se levantaram de madrugada, e juraram um ao outro; e Isaque os despediu, e eles se partiram dele em paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 32, 'E naquele dia sucedeu que vieram os criados de Isaque, e deram-lhe notícias acerca do poço que haviam aberto, e lhe disseram: Achamos água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 33, 'E chamou-o Seba: por cuja causa o nome daquela cidade é Berseba até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 34, 'E quando Esaú foi de quarenta anos, tomou por mulher a Judite filha de Beeri heteu, e a Basemate filha de Elom heteu:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 26, 35, 'E foram amargura de espírito a Isaque e a Rebeca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 1, 'E aconteceu que quando havia Isaque envelhecido, e seus olhos se ofuscaram ficando sem vista, chamou a Esaú, seu filho o maior, e disse-lhe: Meu filho. E ele respondeu: Eis-me aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 2, 'E ele disse: Eis que já sou velho, não sei o dia de minha morte:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 3, 'Toma, pois, agora tuas armas, tua aljava e teu arco, e sai ao campo, e pega-me caça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 4, 'E faze-me um guisado, como eu gosto, e traze-o a mim, e comerei: para que te abençoe minha alma antes que morra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 5, 'E Rebeca estava ouvindo, quando falava Isaque a Esaú seu filho: e foi-se Esaú ao campo para pegar a caça que havia de trazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 6, 'Então Rebeca falou a Jacó seu filho, dizendo: Eis que eu ouvi a teu pai que falava com Esaú teu irmão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 7, 'Traze-me caça, e faze-me um guisado, para que coma, e te abençoe diante do SENHOR antes que eu morra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 8, 'Agora, pois, filho meu, obedece à minha voz no que te mando;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 9, 'Vai agora ao gado, e traze-me dali dois bons cabritos das cabras, e farei deles iguarias para teu pai, como ele gosta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 10, 'E tu as levarás a teu pai, e comerá, para que te abençoe antes de sua morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 11, 'E Jacó disse a Rebeca sua mãe: Eis que Esaú meu irmão é homem peludo, e eu liso:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 12, 'Talvez meu pai me apalpe, e me terá por enganador, e trarei sobre mim maldição e não bênção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 13, 'E sua mãe respondeu: Filho meu, sobre mim tua maldição: somente obedece à minha voz, e vai e traze-os a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 14, 'Então ele foi, e tomou, e trouxe-os à sua mãe: e sua mãe fez guisados, como seu pai gostava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 15, 'E tomou Rebeca as roupas de Esaú seu filho maior, as melhores, que ela tinha em casa, e vestiu a Jacó seu filho menor:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 16, 'E fez-lhe vestir sobre suas mãos e sobre o pescoço onde não tinha pelo, as peles dos cabritos das cabras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 17, 'E entregou os guisados e o pão que havia preparado, em mão de Jacó seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 18, 'E ele foi a seu pai, e disse: Meu pai: e ele respondeu: Eis-me aqui, quem és, filho meu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 19, 'E Jacó disse a seu pai: Eu sou Esaú teu primogênito; fiz como me disseste: levanta-te agora, e senta, e come de minha caça, para que me abençoe tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 20, 'Então Isaque disse a seu filho: Como é que a achaste tão depressa, filho meu? E ele respondeu: Porque o SENHOR teu Deus fez que se encontrasse diante de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 21, 'E Isaque disse a Jacó: Aproxima-te agora, e te apalparei, filho meu, para [que eu saiba] se és meu filho Esaú ou não.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 22, 'E chegou-se Jacó a seu pai Isaque; e ele lhe apalpou, e disse: A voz é a voz de Jacó, mas as mãos, as mãos de Esaú.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 23, 'E não lhe reconheceu, porque suas mãos eram peludas como as mãos de Esaú: e lhe abençoou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 24, 'E disse: És tu meu filho Esaú? E ele respondeu: Eu sou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 25, 'E disse: Aproxima-a a mim, e comerei da caça de meu filho, para que te abençoe minha alma; e ele a aproximou, e comeu: trouxe-lhe também vinho, e bebeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 26, 'E disse-lhe Isaque seu pai: Aproxima-te agora, e beija-me, filho meu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 27, 'E ele se chegou, e lhe beijou; e cheirou Isaque o cheiro de suas roupas, e lhe abençoou, e disse: Eis que o cheiro de meu filho é como o cheiro do campo que o SENHOR abençoou;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 28, 'Deus, pois, te dê do orvalho do céu, e das gorduras da terra, e abundância de trigo e de mosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 29, 'Sirvam-te povos, E nações se inclinem a ti: Sê senhor de teus irmãos, e inclinem-se a ti os filhos de tua mãe; malditos os que te amaldiçoarem, e benditos os que te abençoarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 30, 'E aconteceu, logo que havia Isaque de abençoar a Jacó, e apenas havia saído Jacó de diante de Isaque seu pai, que Esaú seu irmão veio de sua caça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 31, 'E também ele fez guisado, e trouxe a seu pai, e disse-lhe: Levante-se meu pai, e coma da caça de seu filho, para que me abençoe tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 32, 'Então Isaque seu pai lhe disse: Quem és tu? E ele disse: Eu sou teu filho, teu primogênito, Esaú.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 33, 'E Estremeceu-se Isaque com grande estremecimento, e disse: Quem é o que veio aqui, que agarrou caça, e me trouxe, e comi de tudo antes que viesses? Eu o abençoei, e será bendito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 34, 'Quando Esaú ouviu as palavras de seu pai clamou com uma muito grande e muito amarga exclamação, e lhe disse: Abençoa também a mim, meu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 35, 'E ele disse: Veio teu irmão com engano, e tomou tua bênção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 36, 'E ele respondeu: Bem chamaram seu nome Jacó, que já me enganou duas vezes; tirou minha primogenitura, e eis que agora tomou minha bênção. E disse: Não guardaste bênção para mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 37, 'Isaque respondeu e disse a Esaú: Eis que eu o pus por senhor teu, e lhe dei por servos a todos os seus irmãos: de trigo e de vinho lhe provi: que, pois, farei a ti agora, filho meu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 38, 'E Esaú respondeu a seu pai: Não tens mais que uma só bênção, meu pai? Abençoa também a mim, meu pai. E levantou Esaú sua voz, e chorou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 39, 'Então Isaque seu pai falou e disse-lhe: Eis que será tua habitação sem gorduras da terra, E sem orvalho dos céus de acima;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 40, 'E por tua espada viverás, e a teu irmão servirás: E sucederá quando te dominares, Que descarregarás seu jugo de teu pescoço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 41, 'E odiou Esaú a Jacó pela bênção com que lhe havia abençoado, e disse em seu coração: Chegarão os dias do luto de meu pai, e eu matarei a Jacó meu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 42, 'E foram ditas a Rebeca as palavras de Esaú seu filho mais velho: e ela enviou e chamou a Jacó seu filho mais novo, e disse-lhe: Eis que, Esaú teu irmão se consola acerca de ti com a ideia de matar-te.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 43, 'Agora, pois, filho meu, obedece à minha voz; levanta-te, e foge-te a Labão meu irmão, a Harã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 44, 'E mora com ele alguns dias, até que a ira de teu irmão se diminua;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 45, 'Até que se aplaque a ira de teu irmão contra ti, e se esqueça do que lhe fizeste: eu enviarei então, e te trarei dali: por que serei privada de vós ambos em um dia?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 27, 46, 'E disse Rebeca a Isaque: Desgosto tenho de minha vida, por causa das filhas de Hete. Se Jacó toma mulher das filhas de Hete, como estas, das filhas desta terra, para que quero a vida?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 1, 'Então Isaque chamou a Jacó, e o abençoou, e mandou-lhe dizendo: Não tomes mulher das filhas de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 2, 'Levanta-te, vai a Padã-Arã, à casa de Betuel, pai de tua mãe, e toma ali mulher das filhas de Labão, irmão de tua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 3, 'E o Deus Todo-Poderoso te abençoe e te faça frutificar, e te multiplique, até vir a ser congregação de povos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 4, 'E te dê a bênção de Abraão, e à tua descendência contigo, para que herdes a terra de tuas peregrinações, que Deus deu a Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 5, 'Assim enviou Isaque a Jacó, o qual foi a Padã-Arã, a Labão, filho de Betuel arameu, irmão de Rebeca, mãe de Jacó e de Esaú.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 6, 'E viu Esaú como Isaque havia abençoado a Jacó, e lhe havia enviado a Padã-Arã, para tomar para si mulher dali; e que quando lhe abençoou, lhe havia mandado, dizendo: Não tomarás mulher das filhas de Canaã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 7, 'E que Jacó havia obedecido a seu pai e a sua mãe, e se havia ido a Padã-Arã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 8, 'Esaú viu que as filhas de Canaã pareciam mal ao seu pai Isaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 9, 'Então Esaú foi a Ismael, e tomou para si por mulher, além de suas outras mulheres, a Maalate, filha de Ismael, filho de Abraão, irmã de Nebaiote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 10, 'E Jacó saiu de Berseba, e foi a Harã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 11, 'ele chegou a um lugar, e ali dormiu, porque o sol já se havia posto. E tomou uma das pedras daquele lugar e a pôs por sua cabeceira, e deitou-se naquele lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 12, 'E sonhou, e eis uma escada que estava posta na terra, e seu topo tocava no céu; e eis que anjos de Deus subiam e desciam por ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 13, 'E eis que o SENHOR estava no alto dela, e disse: “Eu sou o SENHOR, o Deus de teu pai Abraão, e o Deus de Isaque; a terra em que estás deitado, eu a darei a ti e à tua descendência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 14, 'E a tua descendência será como o pó da terra, e te estenderás ao ocidente, ao oriente, ao norte, e ao sul; e todas as famílias da terra serão abençoadas em ti e na tua descendência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 15, 'E eis que eu estou contigo, e te guardarei por onde quer que fores, e te farei voltar a esta terra; porque não te deixarei, até que eu tenha feito o que te disse.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 16, 'Jacó despertou-se de seu sonho, e disse: “Certamente o SENHOR está neste lugar, e eu não sabia.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 17, 'E teve medo, e disse: “Quão temível é este lugar! Não é outra coisa, senão casa de Deus e porta do céu.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 18, 'Jacó levantou-se de manhã cedo, tomou a pedra que havia colocado de cabeceira, e a pôs por coluna, e derramou azeite sobre ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 19, 'E chamou o nome daquele lugar Betel, porém antes o nome da cidade era Luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 20, 'E Jacó fez um voto, dizendo: “Se Deus for comigo, e me guardar nesta viagem que vou, e me der pão para comer e roupa para vestir,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 21, 'e se eu voltar em paz à casa de meu pai, o SENHOR será meu Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 28, 22, 'e esta pedra que pus por coluna será casa de Deus; e de tudo o que me deres, darei a ti o dízimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 1, 'E Jacó seguiu o seu caminho, e foi à terra dos filhos do oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 2, 'E olhou, e viu um poço no campo: e eis três rebanhos de ovelhas que estavam deitados próximo dele; porque daquele poço davam de beber aos gados: e havia uma grande pedra sobre a boca do poço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 3, 'E juntavam-se ali todos os rebanhos; e revolviam a pedra de sobre a boca do poço, e davam de beber às ovelhas; e voltavam a pedra sobre a boca do poço a seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 4, 'E disse-lhes Jacó: Irmãos meus, de onde sois? E eles responderam: De Harã somos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 5, 'E ele lhes disse: Conheceis a Labão, filho de Naor? E eles disseram: Sim, nós o conhecemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 6, 'E ele lhes disse: Ele está bem? E eles disseram: Está bem; e eis que Raquel sua filha vem com o gado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 7, 'E ele disse: Eis que ainda é cedo do dia; não é hora de recolher o gado; dai de beber às ovelhas, e ide apascentá-las.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 8, 'E eles responderam: Não podemos, até que se juntem todos os gados, e removam a pedra de sobre a boca do poço, para que demos de beber às ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 9, 'Estando ainda ele falando com eles Raquel veio com o gado de seu pai, porque ela era a pastora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 10, 'E sucedeu que, quando Jacó viu Raquel, filha de Labão irmão de sua mãe, e as ovelhas de Labão, o irmão de sua mãe, chegou-se Jacó, e removeu a pedra de sobre a boca do poço, e deu de beber ao gado de Labão irmão de sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 11, 'E Jacó beijou a Raquel, e levantou sua voz, e chorou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 12, 'E Jacó disse a Raquel como ele era irmão de seu pai, e como era filho de Rebeca: e ela correu, e deu as novas a seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 13, 'E assim que ouviu Labão as novas de Jacó, filho de sua irmã, correu a recebê-lo, e abraçou-o, e beijou-o, e trouxe-lhe à sua casa: e ele contou a Labão todas estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 14, 'E Labão lhe disse: Certamente és osso meu e carne minha. E esteve com ele durante um mês.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 15, 'Então disse Labão a Jacó: Por ser tu meu irmão, me hás de servir de graça? Declara-me o que será teu salário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 16, 'E Labão tinha duas filhas: o nome da mais velha era Lia, e o nome da mais nova, Raquel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 17, 'E os olhos de Lia eram tenros, mas Raquel era de lindo semblante e de bela aparência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 18, 'E Jacó amou a Raquel, e disse: Eu te servirei sete anos por Raquel tua filha mais nova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 19, 'E Labão respondeu: Melhor é que a dê a ti, que não que a dê a outro homem: fica-te comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 20, 'Assim serviu Jacó por Raquel sete anos: e pareceram-lhe como poucos dias, porque a amava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 21, 'E disse Jacó a Labão: Dá-me minha mulher, porque meu tempo é cumprido para que me deite com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 22, 'Então Labão juntou a todos os homens daquele lugar, e fez banquete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 23, 'E sucedeu que à noite tomou sua filha Lia, e a trouxe; e ele se deitou com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 24, 'E deu Labão sua serva Zilpa à sua filha Lia por criada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 25, 'E vinda a manhã, eis que era Lia: e ele disse a Labão: Que é isto que me fizeste? Não te servi por Raquel? Por que, pois, me enganaste?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 26, 'E Labão respondeu: Não se faz assim em nosso lugar, que se dê a mais nova antes da mais velha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 27, 'Cumpre a semana desta, e se te dará também a outra, pelo serviço que fizeres comigo por outros sete anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 28, 'E fez Jacó assim, e cumpriu a semana daquela; e ele lhe deu a sua filha Raquel por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 29, 'E deu Labão a Raquel sua filha por criada a sua serva Bila.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 30, 'E deitou-se também com Raquel: e amou-a também mais que a Lia: e serviu a ele ainda outros sete anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 31, 'E viu o SENHOR que Lia era mal-amada, e abriu sua madre; mas Raquel era estéril.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 32, 'E concebeu Lia, e deu à luz um filho, e chamou seu nome Rúben, porque disse: Já que olhou o SENHOR minha aflição; agora, portanto, meu marido me amará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 33, 'E concebeu outra vez, e deu à luz um filho, e disse: Porquanto ouviu o SENHOR que eu era mal-amada, me deu também este. E chamou seu nome Simeão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 34, 'E concebeu outra vez, e deu à luz um filho, e disse: Agora esta vez meu marido se apegará a mim, porque lhe dei três filhos; portanto, chamou seu nome Levi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 29, 35, 'E concebeu outra vez, e deu à luz um filho, e disse: Esta vez louvarei ao SENHOR; por isto chamou seu nome Judá; e deixou de dar à luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 1, 'E vendo Raquel que não dava filhos a Jacó, teve inveja de sua irmã, e dizia a Jacó: Dá-me filhos, ou senão, morro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 2, 'E Jacó se irritava contra Raquel, e dizia: Estou eu em lugar de Deus, que te impediu o fruto de teu ventre?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 3, 'E ela disse: Eis aqui minha serva Bila; deita-te com ela, e dará à luz sobre meus joelhos, e eu também terei filhos por meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 4, 'Assim lhe deu a Bila sua serva por mulher; e Jacó se deitou com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 5, 'E concebeu Bila, e deu à luz a Jacó um filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 6, 'E disse Raquel: Julgou-me Deus, e também ouviu minha voz, e deu-me um filho. Portanto chamou seu nome Dã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 7, 'E concebeu outra vez Bila, a serva de Raquel, e deu à luz o segundo filho a Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 8, 'E disse Raquel: Com lutas de Deus disputei com minha irmã, e venci. E chamou seu nome Naftali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 9, 'E vendo Lia que havia deixado de dar à luz, tomou a Zilpa sua serva, e deu-a a Jacó por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 10, 'E Zilpa, serva de Lia, deu à luz a Jacó um filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 11, 'E disse Lia: Veio a boa sorte. E chamou seu nome Gade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 12, 'E Zilpa, a sirva de Lia, deu à luz outro filho a Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 13, 'E disse Lia: Para alegria minha; porque as mulheres me chamarão de feliz; e chamou seu nome Aser.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 14, 'E foi Rúben em tempo da colheita dos trigos, e achou mandrágoras no campo, e trouxe-as a sua mãe Lia; e disse Raquel a Lia: Rogo-te que me dês das mandrágoras de teu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 15, 'E ela respondeu: É pouco que tenhas tomado meu marido, mas também levarás as mandrágoras de meu filho? E disse Raquel: Ele, pois, dormirá contigo esta noite pelas mandrágoras de teu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 16, 'E quando Jacó voltava do campo à tarde, Lia saiu ao encontro dele, e lhe disse: Deitarás comigo, porque em verdade te aluguei em troca das mandrágoras de meu filho. E dormiu com ela naquela noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 17, 'E ouviu Deus a Lia; e concebeu, e deu à luz a Jacó o quinto filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 18, 'E disse Lia: Deus me deu minha recompensa, porque dei minha serva a meu marido; por isso chamou seu nome Issacar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 19, 'E concebeu Lia outra vez, e deu à luz o sexto filho a Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 20, 'E disse Lia: Deus me deu uma boa dádiva: agora meu marido morará comigo, porque lhe dei seis filhos; e chamou seu nome Zebulom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 21, 'E depois deu à luz uma filha, e chamou seu nome Diná.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 22, 'E lembrou-se Deus de Raquel, e Deus a ouviu, e abriu sua madre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 23, 'E concebeu, e deu à luz um filho: e disse: Deus tirou minha humilhação;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 24, 'E chamou seu nome José, dizendo: Acrescente-me o SENHOR outro filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 25, 'E aconteceu, quando Raquel havia dado à luz a José, que Jacó disse a Labão: Permite-me ir embora, e irei a meu lugar, e à minha terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 26, 'Dá-me minhas mulheres e meus filhos, pelas quais servi contigo, e deixa-me ir; pois tu sabes os serviços que te fiz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 27, 'E Labão lhe respondeu: Ache eu agora favor em teus olhos, e fica-te; experimentei que o SENHOR me abençoou por tua causa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 28, 'E disse: Define-me teu salário, que eu o darei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 29, 'E ele respondeu: Tu sabes como te servi, e como esteve teu gado comigo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 30, 'Porque pouco tinhas antes de minha vinda, e cresceu em grande número; e o SENHOR te abençoou com minha chegada: e agora quando tenho de fazer eu também por minha própria casa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 31, 'E ele disse: Que te darei? E respondeu Jacó: Não me dês nada; se fizeres por mim isto, voltarei a apascentar tuas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 32, 'Eu passarei hoje por todas tuas ovelhas, pondo à parte todas as reses manchadas e de cor variada, e todas as reses de cor escura entre as ovelhas, e as manchadas e de cor variada entre as cabras; e isto será meu salário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 33, 'Assim responderá por mim minha justiça amanhã quando me vier meu salário diante de ti: toda a que não for pintada nem manchada nas cabras e de cor escura nas ovelhas minhas, se me há de ter para furto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 34, 'E disse Labão: Eis que seja como tu dizes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 35, 'Porém ele separou naquele mesmo dia os machos de bode rajados e manchados; e todas as cabras manchadas e de cor variada, e toda rês que tinha em si algo de branco, e todas as de cor escura entre as ovelhas, e as pôs em mãos de seus filhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 36, 'E pôs três dias de caminho entre si e Jacó: e Jacó apascentava as outras ovelhas de Labão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 37, 'E tomou para si Jacó varas de álamo verdes, e de aveleira, e de plátano, e descascou nelas mondaduras brancas, descobrindo assim o branco das varas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 38, 'E pôs as varas que havia riscado nos bebedouros, diante do gado, nos bebedouros da água aonde vinham a beber as ovelhas, as quais se aqueciam vindo a beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 39, 'E concebiam as ovelhas diante das varas, e geravam crias listradas, pintadas e salpicadas de diversas cores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 40, 'E separava Jacó os cordeiros, e os punha com seu rebanho, os listradas, e tudo o que era escuro no rebanho de Labão. E punha seu rebanho à parte, e não o punha com as ovelhas de Labão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 41, 'E sucedia que quantas vezes se aqueciam as fortes, Jacó punha as varas diante das ovelhas nos bebedouros, para que concebessem à vista das varas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 42, 'E quando vinham as ovelhas fracas, não as punha: assim eram as fracas para Labão, e as fortes para Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 30, 43, 'E cresceu o homem muito, e teve muitas ovelhas, e servas, servos, camelos, e asnos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 1, 'E ouvia ele as palavras dos filhos de Labão que diziam: Jacó tomou tudo o que era de nosso pai; e do que era de nosso pai adquiriu toda esta grandeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 2, 'Olhava também Jacó o semblante de Labão, e via que não era para com ele como antes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 3, 'Também o SENHOR disse a Jacó: Volta-te à terra de teus pais, e à tua parentela; que eu serei contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 4, 'E enviou Jacó, e chamou a Raquel e a Lia ao campo a suas ovelhas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 5, 'E disse-lhes: Vejo que o semblante de vosso pai não é para comigo como antes: mas o Deus de meu pai tem sido comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 6, 'E vós sabeis que com todas minhas forças servi a vosso pai:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 7, 'E vosso pai me enganou, e me mudou o salário dez vezes: mas Deus não lhe permitiu que me fizesse mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 8, 'Se ele dizia assim: Os pintados serão teu salário; então todas as ovelhas geravam pintados: e se dizia assim: Os listrados serão teu salário; então todas as ovelhas geravam listrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 9, 'Assim tirou Deus o gado de vosso pai, e deu-o a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 10, 'E sucedeu que ao tempo que as ovelhas se aqueciam, levantei eu meus olhos e vi em sonhos, e eis que os machos que cobriam às fêmeas eram listrados, pintados e malhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 11, 'E disse-me o anjo de Deus em sonhos: Jacó. E eu disse: Eis-me aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 12, 'E ele disse: Levanta agora teus olhos, e verás todos os machos que cobrem às ovelhas são listrados, pintados e malhados; porque eu vi tudo o que Labão te fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 13, 'Eu sou o Deus de Betel, onde tu ungiste a coluna, e onde me fizeste um voto. Levanta-te agora, e sai desta terra, e volta-te à terra de teu nascimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 14, 'E respondeu Raquel e Lia, e disseram-lhe: Temos ainda parte ou herança na casa de nosso pai?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 15, 'Não nos tem já como por estranhas, pois que nos vendeu, e ainda consumiu de todo nosso valor?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 16, 'Porque toda a riqueza que Deus tirou a nosso pai, nossa é e de nossos filhos: agora, pois, faze tudo o que Deus te disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 17, 'Então se levantou Jacó, e subiu seus filhos e suas mulheres sobre os camelos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 18, 'E pôs em caminho todo seu gado, e todos os seus pertences que havia adquirido, o gado de seu ganho que havia obtido em Padã-Arã, para voltar-se a Isaque seu pai na terra de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 19, 'E Labão havia ido tosquiar suas ovelhas; e Raquel furtou os ídolos de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 20, 'E enganou Jacó o coração de Labão arameu, em não lhe fazer saber que se fugia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 21, 'Fugiu, pois, com tudo o que tinha; e levantou-se, e passou o rio, e pôs seu rosto ao monte de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 22, 'E foi dito a Labão ao terceiro dia como Jacó havia fugido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 23, 'Então tomou a seus irmãos consigo, e foi atrás dele caminho de sete dias, e alcançou-lhe no monte de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 24, 'E veio Deus a Labão arameu em sonhos aquela noite, e lhe disse: Guarda-te que não fales a Jacó descomedidamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 25, 'Alcançou, pois, Labão a Jacó, e este havia fixado sua tenda no monte: e Labão pôs a sua com seus irmãos no monte de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 26, 'E disse Labão a Jacó: Que fizeste, que me furtaste o coração, e trouxeste a minhas filhas como prisioneiras de guerra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 27, 'Por que te escondeste para fugir, e me furtaste, e não me deste notícia, para que eu te enviasse com alegria e com cantares, com tamborim e harpa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 28, 'Que ainda não me deixaste beijar meus filhos e minhas filhas. Agora loucamente fizeste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 29, 'Poder há em minha mão para fazer-vos mal; mas o Deus de vosso pai me falou de noite dizendo: Guarda-te que não fales a Jacó descomedidamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 30, 'E já que te ias, porque tinhas saudade da casa de teu pai, por que me furtaste meus deuses?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 31, 'E Jacó respondeu, e disse a Labão: Pois tive medo; porque disse, que talvez me tirasse à força tuas filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 32, 'Em quem achares teus deuses, não viva: diante de nossos irmãos reconhece o que eu tiver teu, e leva-o. Jacó não sabia que Raquel havia os furtado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 33, 'E entrou Labão na tenda de Jacó, e na tenda de Lia, e na tenda das duas servas, e não os achou, e saiu da tenda de Lia, e veio à tenda de Raquel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 34, 'E tomou Raquel os ídolos, e os pôs em uma albarda de um camelo, e sentou-se sobre eles: e provou Labão toda a tenda e não os achou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 35, 'E ela disse a seu pai: Não se ire meu senhor, porque não me posso levantar diante de ti; pois estou com o costume das mulheres. E ele buscou, mas não achou os ídolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 36, 'Então Jacó se irou, e brigou com Labão; e respondeu Jacó e disse a Labão: Que transgressão é a minha? Qual é meu pecado, que com tanto ardor vieste a me perseguir?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 37, 'Depois que apalpaste todos os meus móveis, acaso achaste algum dos objetos de tua casa? Põe-o aqui diante de meus irmãos e teus, e julguem entre nós ambos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 38, 'Estes vinte anos estive contigo; tuas ovelhas e tuas cabras nunca abortaram, nem eu comi carneiro de tuas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 39, 'Nunca te trouxe o arrebatado pelas feras; eu pagava o dano; o furtado tanto de dia como de noite, de minha mão o exigias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 40, 'De dia me consumia o calor, e de noite a geada, e o sono se fugia de meus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 41, 'Assim estive vinte anos em tua casa: catorze anos te servi por tuas duas filhas, e seis anos por teu gado; e mudaste meu salário dez vezes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 42, 'Se o Deus de meu pai, o Deus de Abraão, e o temor de Isaque, não fossem comigo, certamente me enviarias agora vazio; Deus viu minha aflição e o trabalho de minhas mãos, e repreendeu-te de noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 43, 'E respondeu Labão, e disse a Jacó: As filhas são filhas minhas, e os filhos, filhos meus são, e as ovelhas são minhas ovelhas, e tudo o que tu vês é meu; e que posso eu fazer hoje a estas minhas filhas, ou a seus filhos que elas geraram?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 44, 'Vem, pois, agora, façamos aliança eu e tu; e seja em testemunho entre mim e ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 45, 'Então Jacó tomou uma pedra, e levantou-a por coluna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 46, 'E disse Jacó a seus irmãos: Recolhei pedras. E tomaram pedras e fizeram um amontoado; e comeram ali sobre aquele amontoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 47, 'E Labão o chamou Jegar-Saaduta; e Jacó o chamou Galeede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 48, 'Porque Labão disse: Este amontoado é testemunha hoje entre mim e entre ti; por isso foi chamado seu nome Galeede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 49, 'E Mispá, porquanto disse: Vigie o SENHOR entre mim e entre ti, quando nos separarmos um do outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 50, 'Se afligires minhas filhas, ou se tomares outras mulheres além de minhas filhas, ninguém está conosco; olha, Deus é testemunha entre mim e ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 51, 'Disse mais Labão a Jacó: Eis que este amontoado, e eis que esta coluna, que erigi entre mim e ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 52, 'Testemunha seja este amontoado, e testemunha seja esta coluna, que nem eu passarei contra ti este amontoado, nem tu passarás contra mim este amontoado nem esta coluna, para o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 53, 'O Deus de Abraão, e o Deus de Naor julgue entre nós, o Deus de seus pais. E Jacó jurou pelo temor de Isaque seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 54, 'Então Jacó ofereceu sacrifícios no monte, e chamou seus parentes para comer pão; e comeram pão, e dormiram aquela noite no monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 31, 55, 'E levantou-se Labão de manhã, beijou seus filhos e suas filhas, e os abençoou; e retrocedeu e voltou a seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 1, 'E Jacó se foi seu caminho, e saíram-lhe ao encontro anjos de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 2, 'E disse Jacó quando os viu: Este é o acampamento de Deus; e chamou o nome daquele lugar Maanaim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 3, 'E enviou Jacó mensageiros diante de si a Esaú seu irmão, à terra de Seir, campo de Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 4, 'E mandou-lhes dizendo: Assim direis a mim senhor Esaú: Assim diz teu servo Jacó: Com Labão morei, e detive-me até agora;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 5, 'E tenho vacas, e asnos, e ovelhas, e servos, e servas; e envio a dizê-lo a meu senhor, para achar favor em teus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 6, 'E os mensageiros voltaram a Jacó, dizendo: Viemos a teu irmão Esaú, e ele também veio a receber-te, e quatrocentos homens com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 7, 'Então Jacó teve grande temor, e angustiou-se; e partiu o povo que tinha consigo, e as ovelhas e as vacas e os camelos, em dois grupos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 8, 'E disse: Se vier Esaú a um grupo e o ferir, o outro grupo escapará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 9, 'E disse Jacó: Deus de meu pai Abraão, e Deus de meu pai Isaque, o SENHOR, que me disseste: Volta-te à tua terra e à tua parentela, e eu te farei bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 10, 'Menor sou que todas as misericórdias, e que toda a verdade que usaste para com teu servo; que com meu bordão passei este Jordão, e agora estou sobre dois grupos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 11, 'Livra-me agora da mão de meu irmão, da mão de Esaú, porque o temo; não venha talvez, e me fira a mãe com os filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 12, 'E tu disseste: Eu te farei bem, e tornarei tua descendência como a areia do mar, que não se pode contar de tão numerosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 13, 'E dormiu ali aquela noite, e tomou do que lhe veio à mão um presente para seu irmão Esaú.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 14, 'Duzentas cabras e vinte machos de bode, duzentas ovelhas e vinte carneiros,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 15, 'Trinta camelas de cria, com seus filhotes, quarenta vacas e dez novilhos, vinte asnas e dez jumentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 16, 'E entregou-o em mão de seus servos, cada manada à parte; e disse a seus servos: Passai diante de mim, e ponde espaço entre manada e manada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 17, 'E mandou ao primeiro, dizendo: Se meu irmão Esaú te encontrar, e te perguntar, dizendo De quem és? E: Para onde vais? E: para quem é isto que levas diante de ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 18, 'Então dirás: Presente é de teu servo Jacó, que envia a meu senhor Esaú; e eis que também ele vem atrás de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 19, 'E mandou também ao segundo, e ao terceiro, e a todos os que iam atrás aquelas manadas, dizendo: Conforme isto falareis a Esaú, quando o achardes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 20, 'E direis também: Eis que teu servo Jacó vem atrás de nós. Porque disse: Apaziguarei sua ira com o presente que vai adiante de mim, e depois verei seu rosto; talvez lhe serei aceito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 21, 'E passou o presente adiante dele; e ele dormiu aquela noite no acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 22, 'E levantou-se aquela noite, e tomou suas duas mulheres, e suas duas servas, e seus onze filhos, e passou o vau de Jaboque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 23, 'Tomou-os, pois, e passou-os o ribeiro, e fez passar o que tinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 24, 'E ficou Jacó sozinho, e lutou com ele um homem até que raiava a alva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 25, 'E quando viu que não podia com ele, tocou no lugar da juntura de sua coxa, e desconjuntou-se a coxa de Jacó enquanto com ele lutava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 26, 'E disse: Deixa-me, que raia a alva. E ele disse: Não te deixarei, se não me abençoares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 27, 'E ele lhe disse: Qual é teu nome? E ele respondeu: Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 28, 'E ele disse: Não se dirá mais teu nome Jacó, mas sim Israel: porque lutaste com Deus e com os homens, e venceste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 29, 'Então Jacó lhe perguntou, e disse: Declara-me agora teu nome. E ele respondeu: Por que perguntas por meu nome? E abençoou-o ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 30, 'E chamou Jacó o nome daquele lugar Peniel: porque vi a Deus face a face, e foi livrada minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 31, 'E saiu-lhe o sol quando passou a Peniel; e andava mancando de sua coxa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 32, 32, 'Por isto até o dia de hoje os filhos de Israel não comem do tendão que se contrai, o qual está na juntura da coxa; porque o homem tocou a Jacó este lugar de sua coxa no tendão que se contrai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 1, 'E levantando Jacó seus olhos, olhou, e eis que vinha Esaú, e os quatrocentos homens com ele: então repartiu ele os filhos entre Lia e Raquel e as duas servas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 2, 'E pôs as servas e seus filhos adiante; logo a Lia e a seus filhos; e a Raquel e a José os últimos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 3, 'E ele passou diante deles, e inclinou-se à terra sete vezes, até que chegou a seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 4, 'E Esaú correu a seu encontro, e abraçou-lhe, e lançou-se sobre seu pescoço, e o beijou; e choraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 5, 'E levantou seus olhos, e viu as mulheres e os filhos, e disse: Quem são estes que estão contigo? E ele respondeu: São os filhos que Deus deu a teu servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 6, 'E se chegaram as servas, elas e seus meninos, e inclinaram-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 7, 'E chegou-se Lia com seus filhos, e inclinaram-se: e depois chegou José e Raquel, e também se inclinaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 8, 'E ele disse: Qual é a tua intenção com todos estes grupos que encontrei? E ele respondeu: Achar favor aos olhos de meu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 9, 'E disse Esaú: Tenho o bastante, meu irmão; seja para ti o que é teu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 10, 'E disse Jacó: Não, eu te rogo, se achei agora favor em teus olhos, toma meu presente de minha mão, pois vi teu rosto como se houvesse visto o rosto de Deus; e me aceitaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 11, 'Toma, eu te rogo, minha dádiva que te é trazida; porque Deus me fez misericórdia, e tudo o que há aqui é meu. E insistiu com ele, e tomou-a.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 12, 'E disse: Anda, e vamos; e eu irei adiante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 13, 'E ele lhe disse: Meu senhor sabe que os meninos são tenros, e que tenho ovelhas e vacas de cria; e se as cansam, em um dia morrerão todas as ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 14, 'Passe agora meu senhor diante de seu servo, e eu me irei pouco a pouco ao passo do gado que vai adiante de mim, e à passagem dos meninos, até que chegue a meu senhor a Seir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 15, 'E Esaú disse: Deixarei agora contigo da gente que vem comigo. E ele disse: Para que isto? ache eu favor aos olhos de meu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 16, 'Assim se voltou Esaú aquele dia por seu caminho a Seir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 17, 'E Jacó se partiu a Sucote, e edificou ali casa para si, e fez abrigos para seu gado; por isso chamou o nome daquele lugar Sucote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 18, 'E veio Jacó são à cidade de Siquém, que está na terra de Canaã, quando vinha de Padã-Arã; e acampou diante da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 19, 'E comprou uma parte do campo, onde estendeu sua tenda, da mão dos filhos de Hamor, pai de Siquém, por cem peças de moeda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 33, 20, 'E erigiu ali um altar, e chamou-lhe: Deus, o Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 1, 'E saiu Diná a filha de Lia, a qual esta havia dado a Jacó, para ver as mulheres nativas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 2, 'E viu-a Siquém, filho de Hamor heveu, príncipe daquela terra, e tomou-a, e deitou-se com ela, e a desonrou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 3, 'Mas sua alma se apegou a Diná a filha de Lia, e apaixonou-se pela moça, e falou ao coração da jovem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 4, 'E falou Siquém a Hamor seu pai, dizendo: Toma-me por mulher esta moça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 5, 'E ouviu Jacó que havia Siquém violado a Diná sua filha: e estando seus filhos com seu gado no campo, Jacó ficou em silêncio até que eles viessem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 6, 'E dirigiu-se Hamor pai de Siquém a Jacó, para falar com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 7, 'E os filhos de Jacó vieram do campo quando o souberam; e se entristeceram os homens, e se irritaram muito, porque fez depravação em Israel por ter se deitado com a filha de Jacó, o que não se devia haver feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 8, 'E Hamor falou com eles, dizendo: A alma de meu filho Siquém se apegou à vossa filha; rogo-vos que a deis por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 9, 'E aparentai-vos conosco; dai-nos vossas filhas, e tomai vós as nossas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 10, 'E habitai conosco; porque a terra estará diante de vós; morai e negociai nela, e tomai nela possessão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 11, 'Siquém também disse a seu pai e a seus irmãos: Ache eu favor em vossos olhos, e darei o que me disserdes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 12, 'Aumentai muito a exigência de meu dote e presentes, que eu darei quanto me disserdes, e dá-me a moça por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 13, 'E responderam os filhos de Jacó a Siquém e a Hamor seu pai com engano; e falaram, porquanto havia violado a sua irmã Diná.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 14, 'E disseram-lhes: Não podemos fazer isto de dar nossa irmã a homem que tem prepúcio; porque entre nós é abominação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 15, 'Mas com esta condição vos consentiremos: se haveis de ser como nós, que se circuncide entre vós todo homem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 16, 'Então vos daremos nossas filhas, e tomaremos nós as vossas; e habitaremos convosco, e seremos um povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 17, 'Mas se não nos prestardes ouvido para vos circuncidar, tomaremos nossa filha, e nos iremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 18, 'E pareceram bem seus palavras a Hamor e a Siquém, filho de Hamor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 19, 'E não tardou o jovem fazer aquilo, porque a filha de Jacó lhe havia agradado: e ele era o mais honrado de toda a casa de seu pai.')
